import java.util.*;

public class Main {
    static int n;
    static long[] domino;
    static int[] removeOrder;

    static int lisAfter(int k) {
        boolean[] dead = new boolean[n];
        for (int i = 0; i < k; i++) dead[removeOrder[i]] = true;
        long[] tails = new long[n];
        int len = 0;
        for (int i = 0; i < n; i++) {
            if (dead[i]) continue;
            int lo = 0, hi = len;  // first tail >= value (strict LIS)
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (tails[mid] < domino[i]) lo = mid + 1; else hi = mid; }
            tails[lo] = domino[i];
            if (lo == len) len++;
        }
        return len;
    }

    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        n = r.nextInt();
        long minOrder = r.nextLong();
        domino = new long[n];
        removeOrder = new int[n];
        for (int i = 0; i < n; i++) domino[i] = r.nextLong();
        for (int i = 0; i < n; i++) removeOrder[i] = r.nextInt();
        int low = 0, high = n, answer = -1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (lisAfter(mid) >= minOrder) { answer = mid; low = mid + 1; }
            else high = mid - 1;
        }
        System.out.println(answer);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

