	domino := make([]int, n)
	remove := make([]int, n)
	for i := range domino {
		domino[i] = readInt()
	}
	for i := range remove {
		remove[i] = readInt()
	}
	lisAfter := func(k int) int {
		dead := make([]bool, n)
		for _, i := range remove[:k] {
			dead[i] = true
		}
		var tails []int
		for i, v := range domino {
			if dead[i] {
				continue
			}
			pos := sort.SearchInts(tails, v) // first tail >= v (strict LIS)
			if pos == len(tails) {
				tails = append(tails, v)
			} else {
				tails[pos] = v
			}
		}
		return len(tails)
	}
	low, high, answer := 0, n, -1
	for low <= high {
		mid := (low + high) / 2
		if lisAfter(mid) >= minOrder {
			answer = mid
			low = mid + 1
		} else {
			high = mid - 1
		}
	}
	fmt.Println(answer)
}

